mapper.select:
select e.*, u.username, u.nickname
from emotion_diary e
left join user u on e.user_id = u.id


        and e.user_id = #{userId}


        and e.mood_score between #{minScore} and #{maxScore}


order by e.created_at desc

select id
from emotion_diary
where user_id = #{userId}
and diary_date = #{diaryDate}

mapper.update:
update emotion_diary e
join ai_analysis_task t on t.diary_id = e.id
set e.ai_emotion_analysis = #{analysis},
e.ai_analysis_updated_at = #{now}
where t.id = #{taskId}
and t.status = 'PROCESSING'
and e.id = #{snapshot.id}
and e.diary_content      <=> #{snapshot.diaryContent}
and e.mood_score         <=> #{snapshot.moodScore}
and e.dominant_emotion   <=> #{snapshot.dominantEmotion}
and e.emotion_triggers   <=> #{snapshot.emotionTriggers}
and e.sleep_quality      <=> #{snapshot.sleepQuality}
and e.stress_level       <=> #{snapshot.stressLevel}

mapper.select:
select count(1)
from emotion_diary e
join ai_analysis_task t on t.diary_id = e.id
where t.id = #{taskId}
and t.status = 'PROCESSING'
and e.id = #{snapshot.id}
and e.diary_content      <=> #{snapshot.diaryContent}
and e.mood_score         <=> #{snapshot.moodScore}
and e.dominant_emotion   <=> #{snapshot.dominantEmotion}
and e.emotion_triggers   <=> #{snapshot.emotionTriggers}
and e.sleep_quality      <=> #{snapshot.sleepQuality}
and e.stress_level       <=> #{snapshot.stressLevel}

mapper.delete:
delete from ai_analysis_task
where diary_id = #{diaryId}
and status in ('PENDING', 'PROCESSING')
